    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(0);bm=(BatteryManager)getSystemService(BATTERY_SERVICE);prefs=getSharedPreferences("battery42",MODE_PRIVATE);loadHistory();createNotificationChannel();if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},42);buildShell();batteryIntent=registerReceiver(receiver,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(batteryIntent!=null)readBattery(batteryIntent);startBatteryMonitor();}
    int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}
    GradientDrawable shape(int color,int radius,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
    TextView label(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(Math.max(size,11));t.setTextColor(color);t.setFontFeatureSettings("kern");t.setLetterSpacing(bold?0.035f:0.012f);t.setTypeface(Typeface.create("sans-serif",bold?Typeface.BOLD:Typeface.NORMAL));return t;}
    LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
    LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    LinearLayout panel(){LinearLayout p=column();p.setPadding(dp(16),dp(16),dp(16),dp(16));GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff1a2c45,PANEL});bg.setCornerRadius(dp(20));bg.setStroke(dp(1),0x3394a5bb);p.setBackground(bg);p.setElevation(dp(1));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(12);p.setLayoutParams(lp);return p;}
    GradientDrawable accentBg(int a){GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{(a&0xffffff)|0x2e000000,PANEL});g.setCornerRadius(dp(20));g.setStroke(dp(1),(a&0xffffff)|0x66000000);return g;}
    LinearLayout accentPanel(int a){LinearLayout p=panel();p.setBackground(accentBg(a));return p;}
    int severityColor(){return (healthCode==3||healthCode==4||healthCode==5||healthCode==7||temperature>=450)?RED:(temperature>=420||level<=15)?ORANGE:GREEN;}
