    View heroStat(String caption,String value){LinearLayout box=column();box.setGravity(Gravity.CENTER);TextView title=label(caption,9,MUTED,true);title.setGravity(Gravity.CENTER);title.setSingleLine(true);box.addView(title);TextView v=num(value,17,TEXT);v.setGravity(Gravity.CENTER);v.setSingleLine(true);box.addView(v);box.setPadding(dp(3),dp(8),dp(3),dp(8));box.setContentDescription(caption+": "+value);return box;} View verticalDivider(){View v=new View(this);v.setBackgroundColor(0x4494a5bb);return v;}
