    void healthPage(){LinearLayout p=accentPanel(healthCode==2?GREEN:(healthCode==3||healthCode==4||healthCode==5||healthCode==7)?RED:BLUE);int hc=healthColor();LinearLayout hrow=row();LinearLayout badge=new LinearLayout(this);badge.setGravity(Gravity.CENTER);badge.setBackground(shape((hc&0xffffff)|0x26000000,32,(hc&0xffffff)|0x66000000));NavIcon bi=new NavIcon(3);bi.tint=hc;badge.addView(bi,new LinearLayout.LayoutParams(dp(34),dp(34)));hrow.addView(badge,new LinearLayout.LayoutParams(dp(64),dp(64)));LinearLayout ht=column();LinearLayout.LayoutParams htp=new LinearLayout.LayoutParams(0,-2,1);htp.leftMargin=dp(16);hrow.addView(ht,htp);ht.addView(label("СОСТОЯНИЕ АККУМУЛЯТОРА",11,MUTED,true));ht.addView(num(healthText(),30,hc));p.addView(hrow);p.addView(label("Android сообщает системный статус батареи. Это не лабораторная диагностика ёмкости.",12,MUTED,false));content.addView(p);LinearLayout grid=panel();grid.addView(infoLine("Системное здоровье",healthText()));grid.addView(infoLine("Температура",tempText()));grid.addView(infoLine("Технология",techText()));grid.addView(infoLine("Циклы зарядки",cycleText()));grid.addView(infoLine("Оценка износа","Недоступна без проектной ёмкости"));content.addView(grid);LinearLayout note=accentPanel(BLUE);note.addView(label("Почему нет процента износа?",16,TEXT,true));note.addView(label("Стандартный Android API не гарантирует доступ к заводской ёмкости батареи. Поэтому приложение не подменяет реальное измерение случайным процентом. На некоторых моделях доступны дополнительные данные производителя.",12,MUTED,false));content.addView(note);}
