    void addSmartInsights(){LinearLayout box=panel();box.addView(label("SMART INSIGHTS",10,BLUE,true));double rate=dischargeRate();String insight=rate>0?"По последнему непрерывному участку разряда расход составляет около "+String.format(Locale.getDefault(),"%.1f%% в час.",rate):"Нужно накопить непрерывный участок разряда минимум 10 минут для расчёта скорости.";box.addView(label(insight,13,TEXT,true));box.addView(label(temperature>=420?"Следи за нагревом: при высокой температуре лучше временно снизить нагрузку.":temperature>=0?"Температура сейчас не достигла порога предупреждения.":"Датчик температуры пока не передаёт данные.",12,MUTED,false));box.addView(label("Тренды строятся по измерениям телефона; прогнозы не являются гарантией автономности.",11,MUTED,false));content.addView(box);}
    void addAlertSettings(){LinearLayout box=panel();box.addView(label("УВЕДОМЛЕНИЯ И ПОРОГИ",10,BLUE,true));box.addView(label("Выбери, когда приложение должно предупреждать о состоянии аккумулятора.",12,MUTED,false));addSettingsThresholds(box);box.addView(label("По умолчанию: 10% заряда и 42 °C. Температурный порог можно настроить от 38 до 45 °C. Для уведомлений разреши приложению отправку уведомлений в Android.",11,MUTED,false));content.addView(box);}
    String diagnosisTitle(){if(healthCode==3||healthCode==4||healthCode==5||healthCode==7)return "Системное предупреждение";if(temperature>=450)return "Обнаружен перегрев";if(temperature>=420)return "Повышенная температура";if(level<=15)return "Низкий заряд батареи";return "Работа аккумулятора стабильна";}
    String diagnosisDescription(){if(healthCode==3||healthCode==4||healthCode==5||healthCode==7)return "Android сообщил о проблеме состояния батареи: "+healthText()+". Проверь устройство и зарядное оборудование.";if(temperature>=450)return "Температура достигла опасного для комфортной работы уровня. Отключи зарядку и дай телефону остыть.";if(temperature>=420)return "Батарея заметно нагрета. Избегай игр и тяжёлых задач во время зарядки.";if(level<=15)return "Заряд почти закончился. Подключи питание при первой возможности.";return "Критических сигналов по доступным системным датчикам сейчас нет. Наблюдение продолжается в фоне.";}
    boolean isDischargingSample(int i){if(i<0||i>=sampleStatuses.size()||i>=sampleCurrents.size())return false;int current=sampleCurrents.get(i),status=sampleStatuses.get(i);if(current!=Integer.MIN_VALUE&&Math.abs((long)current)>=50000L)return current<0;return status==3;}
    double dischargeRate(){long cutoff=System.currentTimeMillis()-86400000L;int bestFirst=-1,bestLast=-1,runFirst=-1,runLast=-1;for(int i=0;i<Math.min(history.size(),Math.min(sampleTimes.size(),Math.min(sampleStatuses.size(),sampleCurrents.size())));i++){boolean active=sampleTimes.get(i)>=cutoff&&isDischargingSample(i);if(active){if(runFirst<0||sampleTimes.get(i)-sampleTimes.get(runLast)>900000L){if(runFirst>=0&&validDischargeRun(runFirst,runLast)&&(bestFirst<0||sampleTimes.get(runLast)-sampleTimes.get(runFirst)>sampleTimes.get(bestLast)-sampleTimes.get(bestFirst))){bestFirst=runFirst;bestLast=runLast;}runFirst=i;}runLast=i;}else if(runFirst>=0){if(validDischargeRun(runFirst,runLast)&&(bestFirst<0||sampleTimes.get(runLast)-sampleTimes.get(runFirst)>sampleTimes.get(bestLast)-sampleTimes.get(bestFirst))){bestFirst=runFirst;bestLast=runLast;}runFirst=-1;runLast=-1;}}if(runFirst>=0&&validDischargeRun(runFirst,runLast)&&(bestFirst<0||sampleTimes.get(runLast)-sampleTimes.get(runFirst)>sampleTimes.get(bestLast)-sampleTimes.get(bestFirst))){bestFirst=runFirst;bestLast=runLast;}if(bestFirst<0)return -1;long dt=sampleTimes.get(bestLast)-sampleTimes.get(bestFirst);int drop=history.get(bestFirst)-history.get(bestLast);return drop/(dt/3600000.0);}
    boolean validDischargeRun(int first,int last){return first>=0&&last>first&&sampleTimes.get(last)-sampleTimes.get(first)>=600000L&&history.get(first)>history.get(last);}
    String dischargeRateText(){double r=dischargeRate();return r<0?"Собираем данные":String.format(Locale.getDefault(),"≈ %.1f%%/ч",r);}
    long bestDischargeRunMinutes(){long best=0;int first=-1,last=-1;for(int i=0;i<Math.min(history.size(),Math.min(sampleTimes.size(),Math.min(sampleStatuses.size(),sampleCurrents.size())));i++){boolean active=sampleTimes.get(i)>=System.currentTimeMillis()-86400000L&&isDischargingSample(i);if(active){if(last>=0&&sampleTimes.get(i)-sampleTimes.get(last)>900000L){if(first>=0&&last>first&&history.get(first)>history.get(last))best=Math.max(best,(sampleTimes.get(last)-sampleTimes.get(first))/60000L);first=i;}else if(first<0)first=i;last=i;}else if(first>=0){if(last>first&&history.get(first)>history.get(last))best=Math.max(best,(sampleTimes.get(last)-sampleTimes.get(first))/60000L);first=-1;last=-1;}}if(first>=0&&last>first&&history.get(first)>history.get(last))best=Math.max(best,(sampleTimes.get(last)-sampleTimes.get(first))/60000L);return best;}
    String dischargeConfidenceText(){long mins=bestDischargeRunMinutes();int n=dischargeSamples();if(dischargeRate()<0)return "Пока нет подходящего участка";if(mins>=60&&n>=12)return "Хорошая · "+mins+" мин данных";if(mins>=30&&n>=6)return "Средняя · "+mins+" мин данных";return "Предварительная · "+mins+" мин данных";}
    String monitoringStateText(){long t=prefs.getLong("last_sample_time",0L);if(t<=0)return "Ожидает первый замер";long age=Math.max(0,System.currentTimeMillis()-t);if(age<=150000L)return "Активен";if(age<=300000L)return "Задержка записи";return "Нет свежих замеров";}
    String lastSampleAgeText(){long t=prefs.getLong("last_sample_time",0L);if(t<=0)return "Нет данных";long sec=Math.max(0,(System.currentTimeMillis()-t)/1000L);return sec<60?sec+" сек. назад":(sec/60)+" мин. назад";}
    String lastHeartbeatText(){long t=prefs.getLong("service_heartbeat",0L);if(t<=0)return "Нет сигнала";long sec=Math.max(0,(System.currentTimeMillis()-t)/1000L);return sec<60?sec+" сек. назад":(sec/60)+" мин. назад";}
    String averageSampleIntervalText(){if(sampleTimes.size()<2)return "Недостаточно данных";long sum=0;int n=0;for(int i=1;i<sampleTimes.size();i++){long d=sampleTimes.get(i)-sampleTimes.get(i-1);if(d>0&&d<=3600000L){sum+=d;n++;}}return n==0?"Недостаточно данных":String.format(Locale.getDefault(),"≈ %.1f мин",sum/(double)n/60000.0);}
    String estimatedRuntimeText(){double r=dischargeRate();if(r<=0)return "Недостаточно данных";double h=level/r;if(h>240)return "Более 10 дней";int hours=(int)h;int mins=(int)Math.round((h-hours)*60);if(mins>=60){hours++;mins-=60;}return hours+" ч "+mins+" мин · оценка";}
    int dischargeSamples(){int n=0;long cutoff=System.currentTimeMillis()-86400000L;for(int i=0;i<Math.min(sampleStatuses.size(),Math.min(sampleTimes.size(),sampleCurrents.size()));i++)if(sampleTimes.get(i)>=cutoff&&isDischargingSample(i))n++;return n;}
    int hotSamples(){int n=0;for(int t:sampleTemps)if(t>=420)n++;return n;}
    String thermalStatus(){if(temperature<0)return "Нет данных";if(temperature>=450)return "Перегрев";if(temperature>=420)return "Повышенная";if(temperature>=380)return "Тёплая";return "Норма";}
    String maxTemperatureText(){int m=-1;for(int t:sampleTemps)if(t>m)m=t;return m<0?"Нет данных":String.format(Locale.getDefault(),"%.1f °C",m/10f);}
    void shareFullReport(){StringBuilder b=new StringBuilder();b.append("BATTERY MONITOR 42 — ОТЧЁТ\\n");b.append("Создан: ").append(new SimpleDateFormat("dd.MM.yyyy HH:mm",Locale.getDefault()).format(new Date())).append("\\n");b.append("Устройство: ").append(Build.MANUFACTURER).append(" ").append(Build.MODEL).append("\\n");b.append("Android: ").append(Build.VERSION.RELEASE).append(" (API ").append(Build.VERSION.SDK_INT).append(")\\n\\n");b.append("ТЕКУЩИЕ ПОКАЗАТЕЛИ\\nЗаряд: ").append(level).append("%\\nСтатус: ").append(statusText()).append("\\nТемпература: ").append(tempText()).append(" °C\\nНапряжение: ").append(voltageText()).append(" V\\nТок: ").append(currentText()).append(" mA\\nИсточник: ").append(sourceText()).append("\\nЗдоровье: ").append(healthText()).append("\\nЦиклы: ").append(cycleText()).append("\\nТехнология: ").append(techText()).append("\\n\\n");b.append("МОНИТОРИНГ\\nСостояние службы: ").append(monitoringStateText()).append("\\nПоследний замер: ").append(lastSampleAgeText()).append("\\nПоследний сигнал службы: ").append(lastHeartbeatText()).append("\\nИнтервал между замерами: ").append(averageSampleIntervalText()).append("\\n\\n");b.append("АНАЛИТИКА\\nСкорость разряда: ").append(dischargeRateText()).append("\\nДостоверность оценки: ").append(dischargeConfidenceText()).append("\\nОценка времени работы: ").append(estimatedRuntimeText()).append("\\nСредняя температура архива: ").append(averageTemp()).append("\\nМаксимальная температура: ").append(maxTemperatureText()).append("\\nЗамеров выше 42 °C: ").append(hotSamples()).append("\\nЗарядных сессий: ").append(chargeSessions()).append("\\nЗаписей истории: ").append(history.size()).append("\\n\\n");b.append("ПОСЛЕДНИЕ ЗАМЕРЫ\\n");int start=Math.max(0,history.size()-200);for(int i=start;i<history.size();i++){b.append(new SimpleDateFormat("dd.MM HH:mm",Locale.getDefault()).format(new Date(sampleTimes.get(i)))).append(" | ").append(history.get(i)).append("% | ");b.append(sampleTemps.get(i)<0?"—":String.format(Locale.getDefault(),"%.1f °C",sampleTemps.get(i)/10f)).append(" | ").append(sampleStatuses.get(i)==2?"Зарядка":sampleStatuses.get(i)==3?"Разряд":"Ожидание").append("\\n");}b.append("\\nПримечание: время работы и скорость разряда являются оценками по сохранённым измерениям. Android не предоставляет универсальный точный процент износа.");Intent send=new Intent(Intent.ACTION_SEND);send.setType("text/plain");send.putExtra(Intent.EXTRA_SUBJECT,"Battery Monitor 42 — отчёт");send.putExtra(Intent.EXTRA_TEXT,b.toString());startActivity(Intent.createChooser(send,"Поделиться отчётом"));}
    void settingsPage(){
        LinearLayout intro=panel();intro.addView(label("ЦЕНТР УПРАВЛЕНИЯ",10,BLUE,true));intro.addView(label("Настройки приложения",23,TEXT,true));intro.addView(label("Управляй уведомлениями, порогами и данными мониторинга в одном месте.",13,MUTED,false));content.addView(intro);
        LinearLayout alerts=panel();alerts.addView(label("УМНЫЕ УВЕДОМЛЕНИЯ",10,GREEN,true));alerts.addView(label("Предупреждения о низком заряде, перегреве и завершении зарядки.",12,MUTED,false));Switch enabled=new Switch(this);enabled.setText("Включить уведомления");enabled.setTextColor(TEXT);enabled.setTextSize(15);int[][] sw={{android.R.attr.state_checked},{}};enabled.setThumbTintList(new android.content.res.ColorStateList(sw,new int[]{GREEN,0xff94a5bb}));enabled.setTrackTintList(new android.content.res.ColorStateList(sw,new int[]{0x6665e7c0,0x4094a5bb}));enabled.setChecked(prefs.getBoolean("alerts_enabled",true));enabled.setPadding(0,dp(12),0,dp(8));enabled.setOnCheckedChangeListener((button,checked)->{prefs.edit().putBoolean("alerts_enabled",checked).apply();lastAlert=0;});alerts.addView(enabled);addSettingsThresholds(alerts);content.addView(alerts);
        LinearLayout data=panel();data.addView(label("ХРАНЕНИЕ И ДАННЫЕ",10,BLUE,true));data.addView(infoLine("Сохранено измерений",String.valueOf(history.size())));data.addView(infoLine("Период хранения","До 7 дней"));data.addView(infoLine("Последний замер",lastSampleAgeText()));data.addView(infoLine("Средний интервал",averageSampleIntervalText()));LinearLayout.LayoutParams sb1=new LinearLayout.LayoutParams(-1,-2);sb1.topMargin=dp(12);data.addView(actionButton("Экспортировать историю  ↗",BLUE,()->shareHistory()),sb1);LinearLayout.LayoutParams sb2=new LinearLayout.LayoutParams(-1,-2);sb2.topMargin=dp(8);data.addView(actionButton("Создать полный отчёт  ↗",BLUE,()->shareFullReport()),sb2);content.addView(data);
        LinearLayout service=quietPanel();service.addView(label("МОНИТОРИНГ",10,BLUE,true));service.addView(infoLine("Фоновая служба",monitoringStateText()));service.addView(infoLine("Последний сигнал",lastHeartbeatText()));service.addView(label("Мониторинг продолжает собирать данные в фоне. Для стабильной работы разреши уведомления и не ограничивай фоновую активность приложения.",12,MUTED,false));content.addView(service);
        LinearLayout about=quietPanel();about.addView(label("BATTERY MONITOR 42",16,TEXT,true));about.addView(label("Версия 4.4.1 · Stability",13,GREEN,true));about.addView(label("Интеллектуальная аналитика аккумулятора. Все оценки строятся на измерениях устройства; неподдерживаемые Android показатели не подменяются вымышленными значениями.",12,MUTED,false));content.addView(about);LinearLayout danger=accentPanel(RED);danger.addView(label("ОПАСНАЯ ЗОНА",10,RED,true));danger.addView(label("Удалит все сохранённые измерения. Настройки и фоновая служба останутся без изменений.",12,MUTED,false));LinearLayout.LayoutParams db=new LinearLayout.LayoutParams(-1,-2);db.topMargin=dp(12);danger.addView(actionButton("Очистить историю измерений",RED,()->confirmClearHistory()),db);content.addView(danger);
    }
    void addSettingsThresholds(LinearLayout box){int low=prefs.getInt("alert_low",10);TextView lowLabel=label("Порог низкого заряда: "+low+"%",13,TEXT,true);lowLabel.setPadding(0,dp(8),0,dp(2));box.addView(lowLabel);SeekBar lowBar=styledBar();lowBar.setMax(25);lowBar.setProgress(Math.max(0,Math.min(25,low-5)));lowBar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int v,boolean from){int n=v+5;lowLabel.setText("Порог низкого заряда: "+n+"%");if(from)prefs.edit().putInt("alert_low",n).apply();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});box.addView(lowBar);int tempLimit=Math.max(380,Math.min(450,prefs.getInt("alert_temp",420)));TextView tempLabel=label("Предупреждать при температуре от "+String.format(Locale.getDefault(),"%.1f",tempLimit/10f)+" °C",13,TEXT,true);tempLabel.setPadding(0,dp(8),0,dp(2));box.addView(tempLabel);SeekBar tempBar=styledBar();tempBar.setMax(70);tempBar.setProgress(Math.max(0,Math.min(70,tempLimit-380)));tempBar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int v,boolean from){int n=380+v;tempLabel.setText("Предупреждать при температуре от "+String.format(Locale.getDefault(),"%.1f",n/10f)+" °C");if(from)prefs.edit().putInt("alert_temp",n).apply();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});box.addView(tempBar);}
    void confirmClearHistory(){new AlertDialog.Builder(this).setTitle("Очистить историю?").setMessage("Все сохранённые измерения будут удалены. Настройки и фоновый мониторинг останутся без изменений.").setNegativeButton("Отмена",null).setPositiveButton("Очистить",(d,w)->{history.clear();sampleTimes.clear();sampleTemps.clear();sampleCurrents.clear();sampleVoltages.clear();sampleStatuses.clear();saveHistory();buildPage();}).show();}
    void tipsPage(){LinearLayout p=panel();p.addView(label("Умные рекомендации",21,TEXT,true));String advice=advice();p.addView(label(advice,15,GREEN,true));p.addView(label("• Избегай длительного нагрева телефона.\n\n• Не оставляй устройство под прямым солнцем во время зарядки.\n\n• Используй качественный адаптер и кабель.\n\n• Если корпус заметно нагревается, дай телефону остыть.",13,MUTED,false));content.addView(p);LinearLayout n=panel();n.addView(label("Пороговые уведомления",16,TEXT,true));n.addView(label("Доступны предупреждения о низком заряде, высокой температуре и завершении зарядки. Фоновый сервис продолжает собирать измерения с постоянным уведомлением Android. Работа зависит от ограничений фоновой активности производителя телефона.",12,MUTED,false));content.addView(n);}
    String statusText(){return batteryStatus==5?"Полностью заряжен":batteryStatus==2?"Идёт зарядка":batteryStatus==3?"Работает от батареи":"Ожидание";}
    String tempText(){return temperature<0?"Нет данных":String.format(Locale.getDefault(),"%.1f",temperature/10f);}
    String voltageText(){return millivolts<=0?"—":String.format(Locale.getDefault(),"%.2f",millivolts/1000f);}
    String currentText(){return microamps==Integer.MIN_VALUE?"—":String.format(Locale.getDefault(),"%+.0f",microamps/1000f);}
    String sourceText(){return plug==1?"Сеть":plug==2?"USB":plug==4?"Беспроводная":plug==8?"Док":"Нет";}
    String healthText(){switch(healthCode){case 2:return "Хорошее";case 3:return "Перегрев";case 4:return "Неисправность";case 5:return "Перенапряжение";case 7:return "Переохлаждение";default:return "Нет данных";}}
    String techText(){String s=batteryIntent==null?null:batteryIntent.getStringExtra(BatteryManager.EXTRA_TECHNOLOGY);return s==null||s.isEmpty()?"Неизвестно":s;}
    String cycleText(){if(Build.VERSION.SDK_INT>=34&&batteryIntent!=null){int c=batteryIntent.getIntExtra("android.os.extra.CYCLE_COUNT",-1);return c>=0?String.valueOf(c):"Нет данных";}return "Требуется Android 14+";}
    String advice(){if(temperature>=450)return "Высокая температура. Отключи зарядку и дай устройству остыть.";if(level<=15)return "Низкий заряд. Пора подключить зарядное устройство.";if(batteryStatus==2&&temperature>=400)return "Во время зарядки батарея заметно нагрелась.";if(batteryStatus==5)return "Заряд 100%. Можно отключить питание.";return "Показатели в обычном диапазоне. Продолжай наблюдение.";}
    void readBattery(Intent i){int oldLevel=level,oldStatus=batteryStatus,oldPlug=plug,oldTemp=temperature;int lev=i.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),sc=i.getIntExtra(BatteryManager.EXTRA_SCALE,100);if(lev>=0&&sc>0)level=Math.round(lev*100f/sc);temperature=i.getIntExtra(BatteryManager.EXTRA_TEMPERATURE,-1);millivolts=i.getIntExtra(BatteryManager.EXTRA_VOLTAGE,-1);healthCode=i.getIntExtra(BatteryManager.EXTRA_HEALTH,1);plug=i.getIntExtra(BatteryManager.EXTRA_PLUGGED,0);batteryStatus=i.getIntExtra(BatteryManager.EXTRA_STATUS,1);microamps=bm.getIntProperty(BatteryManager.BATTERY_PROPERTY_CURRENT_NOW);if(history.isEmpty()||oldLevel!=level||oldStatus!=batteryStatus||oldPlug!=plug||(oldTemp>=0&&Math.abs(oldTemp-temperature)>=10)){recordSample();}checkAlerts();if(pct!=null){pct.setText(level+"%");status.setText(statusText());ring.invalidate();}if(eta!=null){long ms=Build.VERSION.SDK_INT>=28?bm.computeChargeTimeRemaining():-1;if(ms<=0&&batteryStatus==2){long minutes=estimatedRemainingMinutes();if(minutes>0)ms=minutes*60000L;}eta.setText(ms>0&&batteryStatus==2?"До полного заряда примерно "+formatTime(ms)+" · оценка":" ");}if(page.equals("Обзор"))buildPage();}
    String chargingEtaText(){if(batteryStatus!=2)return "Прогноз доступен во время зарядки";long ms=Build.VERSION.SDK_INT>=28?bm.computeChargeTimeRemaining():-1;if(ms>0)return "До полного заряда примерно "+formatTime(ms)+" · оценка";long minutes=estimatedRemainingMinutes();if(minutes>0)return "До полного заряда примерно "+(minutes/60)+" ч "+(minutes%60)+" мин · оценка";return "Зарядка идёт · собираем данные для прогноза";}
    String formatTime(long ms){long m=ms/60000;return (m/60)+" ч "+(m%60)+" мин";}
    void recordSample(){reloadHistoryFromPrefs();if(page.equals("Обзор")||page.equals("История")){quiet=true;buildPage();quiet=false;}}
    @Override protected void onResume(){super.onResume();sampleHandler.removeCallbacks(sampleTask);sampleHandler.postDelayed(sampleTask,60000);}
    @Override protected void onPause(){sampleHandler.removeCallbacks(sampleTask);super.onPause();}
    void loadHistory(){String v2=prefs.getString("history_v2","");if(!v2.isEmpty()){try{for(String entry:v2.split(";")){String[] a=entry.split(":");if(a.length==6){sampleTimes.add(Long.parseLong(a[0]));history.add(Integer.parseInt(a[1]));sampleTemps.add(Integer.parseInt(a[2]));sampleCurrents.add(Integer.parseInt(a[3]));sampleVoltages.add(Integer.parseInt(a[4]));sampleStatuses.add(Integer.parseInt(a[5]));}}}catch(Exception e){history.clear();sampleTimes.clear();sampleTemps.clear();sampleCurrents.clear();sampleVoltages.clear();sampleStatuses.clear();}}else{String s=prefs.getString("history","");if(!s.isEmpty())try{for(String x:s.split(",")){history.add(Integer.parseInt(x));sampleTimes.add(System.currentTimeMillis());sampleTemps.add(-1);sampleCurrents.add(Integer.MIN_VALUE);sampleVoltages.add(-1);sampleStatuses.add(1);}}catch(Exception e){history.clear();}}}
    void reloadHistoryFromPrefs(){history.clear();sampleTimes.clear();sampleTemps.clear();sampleCurrents.clear();sampleVoltages.clear();sampleStatuses.clear();String v=prefs.getString("history_v2","");if(!v.isEmpty()){try{for(String entry:v.split(";")){String[] a=entry.split(":");if(a.length==6){sampleTimes.add(Long.parseLong(a[0]));history.add(Integer.parseInt(a[1]));sampleTemps.add(Integer.parseInt(a[2]));sampleCurrents.add(Integer.parseInt(a[3]));sampleVoltages.add(Integer.parseInt(a[4]));sampleStatuses.add(Integer.parseInt(a[5]));}}}catch(Exception ignored){history.clear();sampleTimes.clear();sampleTemps.clear();sampleCurrents.clear();sampleVoltages.clear();sampleStatuses.clear();}}}
    void startBatteryMonitor(){Intent i=new Intent(this,BatteryMonitorService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}
    void saveHistory(){StringBuilder b=new StringBuilder();for(int i=0;i<history.size();i++){if(b.length()>0)b.append(";");b.append(sampleTimes.get(i)).append(":").append(history.get(i)).append(":").append(sampleTemps.get(i)).append(":").append(sampleCurrents.get(i)).append(":").append(sampleVoltages.get(i)).append(":").append(sampleStatuses.get(i));}prefs.edit().putString("history_v2",b.toString()).putString("history",history.toString()).apply();}
    int chargeSessions(){int n=0;boolean charging=false;for(int s:sampleStatuses){boolean now=s==2;if(now&&!charging)n++;charging=now;}return n;}
    String averageTemp(){int sum=0,n=0;for(int t:sampleTemps)if(t>=0){sum+=t;n++;}return n==0?"Нет данных":String.format(Locale.getDefault(),"%.1f °C",sum/(float)n/10f);}
    int activeChargeStart(){if(sampleStatuses.isEmpty()||sampleStatuses.get(sampleStatuses.size()-1)!=2)return -1;int first=sampleStatuses.size()-1;while(first>0&&sampleStatuses.get(first-1)==2)first--;return first;}
    double activeChargeRate(){int first=activeChargeStart(),last=sampleStatuses.size()-1;if(first<0||last<=first)return -1;long mins=(sampleTimes.get(last)-sampleTimes.get(first))/60000L;int delta=history.get(last)-history.get(first);if(mins<2||delta<=0)return -1;return delta*60.0/mins;}
    String chargingRate(){if(activeChargeStart()<0)return "Нет активной зарядки";double rate=activeChargeRate();return rate<0?"Собираем данные":String.format(Locale.getDefault(),"≈ %.1f%%/ч",rate);}
    String forecastText(int target){if(batteryStatus!=2)return "Доступен во время зарядки";if(level>=target)return "Уже достигнуто";double rate=activeChargeRate();if(rate<1)return "Собираем данные";long mins=Math.max(1,Math.round((target-level)*60.0/rate));return "≈ "+formatMinutes(mins);}
    String formatMinutes(long mins){return (mins/60)+" ч "+(mins%60)+" мин";}
    String currentSessionText(){int first=activeChargeStart(),last=sampleStatuses.size()-1;if(first<0)return "Нет активной сессии";long mins=Math.max(0,(sampleTimes.get(last)-sampleTimes.get(first))/60000L);int gained=history.get(last)-history.get(first);return (gained>0?"+"+gained+"% · ":"")+formatMinutes(mins);}
    boolean isSlowCharging(){int first=activeChargeStart(),last=sampleStatuses.size()-1;if(first<0||last<=first)return false;long mins=(sampleTimes.get(last)-sampleTimes.get(first))/60000L;double rate=activeChargeRate();return mins>=10&&rate>=0&&rate<5.0;}
    String slowChargeText(){if(batteryStatus!=2)return "Подключи зарядное устройство, чтобы увидеть аналитику.";int first=activeChargeStart(),last=sampleStatuses.size()-1;if(first<0||last<=first)return "Собираем измерения для оценки скорости.";if(isSlowCharging())return "Зарядка медленнее обычного. Проверь кабель, адаптер и температуру.";if(activeChargeRate()<0)return "Наблюдаем за зарядкой — оценка появится после новых измерений.";return "Скорость оценивается по последним измерениям и может меняться.";}
    long estimatedRemainingMinutes(){if(sampleStatuses.isEmpty()||sampleStatuses.get(sampleStatuses.size()-1)!=2)return -1;int last=sampleStatuses.size()-1,first=last;while(first>0&&sampleStatuses.get(first-1)==2)first--;if(last<=first)return -1;long mins=(sampleTimes.get(last)-sampleTimes.get(first))/60000;int delta=history.get(last)-history.get(first);if(mins<2||delta<=0)return -1;double rate=delta*60.0/mins;if(rate<1.0)return -1;return Math.max(1,Math.round((100-level)*60.0/rate));}
    String lastSampleTime(){if(sampleTimes.isEmpty())return "Нет данных";return new SimpleDateFormat("dd.MM HH:mm",Locale.getDefault()).format(new Date(sampleTimes.get(sampleTimes.size()-1)));}
    String firstSampleTime(){if(sampleTimes.isEmpty())return "Нет данных";return new SimpleDateFormat("dd.MM HH:mm",Locale.getDefault()).format(new Date(sampleTimes.get(0)));}
    void addSessionRows(LinearLayout box){ArrayList<Integer> starts=new ArrayList<>(),ends=new ArrayList<>();boolean active=false;int start=0;for(int i=0;i<sampleStatuses.size();i++){boolean charging=sampleStatuses.get(i)==2;if(charging&&!active){start=i;active=true;}if(active&&(!charging||i==sampleStatuses.size()-1)){int end=charging?i:i-1;starts.add(start);ends.add(end);active=false;}}if(starts.isEmpty()){box.addView(label("Зарядные сессии появятся после накопления данных.",12,MUTED,false));return;}int shown=0;for(int n=starts.size()-1;n>=0&&shown<8;n--,shown++){int a=starts.get(n),b=ends.get(n);long duration=Math.max(0,(sampleTimes.get(b)-sampleTimes.get(a))/60000L);int gain=history.get(b)-history.get(a);String date=new SimpleDateFormat("dd.MM · HH:mm",Locale.getDefault()).format(new Date(sampleTimes.get(a)));box.addView(infoLine(date,(gain>=0?"+":"")+gain+"% · "+formatMinutes(duration)));}}
    void shareHistory(){StringBuilder b=new StringBuilder("Battery Monitor 42 — история\n");for(int i=0;i<history.size();i++)b.append(new SimpleDateFormat("dd.MM HH:mm",Locale.getDefault()).format(new Date(sampleTimes.get(i)))).append(" | ").append(history.get(i)).append("% | ").append(sampleTemps.get(i)<0?"—":sampleTemps.get(i)/10f+" °C").append("\n");Intent send=new Intent(Intent.ACTION_SEND);send.setType("text/plain");send.putExtra(Intent.EXTRA_TEXT,b.toString());startActivity(Intent.createChooser(send,"Экспорт истории"));}
    void createNotificationChannel(){if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel("battery42_alerts","Состояние аккумулятора",NotificationManager.IMPORTANCE_DEFAULT);ch.setDescription("Предупреждения о температуре и уровне заряда");((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(ch);}}
    void checkAlerts(){if(!prefs.getBoolean("alerts_enabled",true))return;int tempLimit=prefs.getInt("alert_temp",420),lowLimit=prefs.getInt("alert_low",10);int alert=temperature>=tempLimit?2:level<=lowLimit?1:(batteryStatus==5?3:0);if(alert==0){lastAlert=0;prefs.edit().putInt("last_alert",0).apply();return;}if(alert==lastAlert)return;lastAlert=alert;prefs.edit().putInt("last_alert",alert).apply();if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return;String title=alert==2?"Перегрев аккумулятора":alert==1?"Низкий заряд":"Зарядка завершена";String body=alert==2?"Температура "+tempText()+" °C. Отключи зарядку и дай телефону остыть.":alert==1?"Осталось "+level+"% заряда. Подключи зарядное устройство.":"Аккумулятор заряжен до 100%.";Notification.Builder nb=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"battery42_alerts"):new Notification.Builder(this);nb.setSmallIcon(android.R.drawable.ic_lock_idle_charging).setContentTitle(title).setContentText(body).setAutoCancel(true);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(42,nb.build());}
    class TemperatureChart extends View{Paint p=new Paint(3);float reveal=(chartsRevealed||reducedMotion())?1f:0f;TemperatureChart(){super(MainActivity.this);}protected void onDraw(Canvas c){c.save();c.clipRect(0,0,getWidth()*reveal,getHeight());draw0(c);c.restore();if(reveal<1f){reveal=Math.min(1f,reveal+.05f);postInvalidateOnAnimation();}else chartsRevealed=true;}void draw0(Canvas c){float w=getWidth(),h=getHeight(),l=dp(8),r=w-dp(8),t=dp(8),b=h-dp(8);p.setColor(0x2694a5bb);p.setStrokeWidth(dp(1));for(int j=0;j<3;j++){float y=t+(b-t)*j/2f;c.drawLine(l,y,r,y,p);}int count=0;for(int x:sampleTemps)if(x>=0)count++;if(count<2){p.setColor(MUTED);p.setTextSize(dp(11));c.drawText("Собираем данные о температуре…",l,b-dp(5),p);return;}p.setColor(ORANGE);p.setStrokeWidth(dp(2.5f));p.setStyle(Paint.Style.STROKE);Path path=new Path();int seen=0;for(int i=0;i<sampleTemps.size();i++){int v=sampleTemps.get(i);if(v<0)continue;float x=l+(r-l)*seen/(float)(count-1),y=b-(b-t)*Math.max(0,Math.min(600,v))/600f;if(seen++==0)path.moveTo(x,y);else path.lineTo(x,y);}int lc=p.getColor();Path fp=new Path(path);fp.lineTo(r,b);fp.lineTo(l,b);fp.close();p.setStyle(Paint.Style.FILL);p.setShader(new LinearGradient(0,t,0,b,(lc&0xffffff)|0x55000000,lc&0xffffff,Shader.TileMode.CLAMP));c.drawPath(fp,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);c.drawPath(path,p);p.setStyle(Paint.Style.FILL);}}
